'use strict';
(()=>{
 const by=id=>document.getElementById(id),button=document.createElement('button');button.className='button';button.textContent='✎ Write page';button.id='writeBtn';by('importBtn').after(button);
 const canvas=by('inkCanvas'),display=canvas.getContext('2d'),ink=document.createElement('canvas'),ic=ink.getContext('2d');let strokes=[],redo=[],active=null,inkTool='pen',size={w:148,h:210};
 function coords(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),pressure:e.pointerType==='pen'&&e.pressure>0?e.pressure:.5};}
 function segment(s,a,b){const unit=canvas.width/size.w;ic.save();ic.globalCompositeOperation=s.tool==='eraser'?'destination-out':'source-over';ic.strokeStyle=s.color;ic.fillStyle=s.color;ic.lineCap='round';ic.lineJoin='round';ic.lineWidth=s.widthMm*unit*(s.tool==='eraser'?10:.65+(a.pressure+b.pressure)*.5);ic.beginPath();ic.moveTo(a.x*canvas.width,a.y*canvas.height);ic.lineTo(b.x*canvas.width,b.y*canvas.height);ic.stroke();if(a===b){ic.beginPath();ic.arc(a.x*canvas.width,a.y*canvas.height,ic.lineWidth/2,0,Math.PI*2);ic.fill();}ic.restore();}
 function paint(){display.fillStyle='#fffefa';display.fillRect(0,0,canvas.width,canvas.height);const step=canvas.width/size.w*5;display.fillStyle='#d5d8cf';for(let y=step/2;y<canvas.height;y+=step)for(let x=step/2;x<canvas.width;x+=step){display.beginPath();display.arc(x,y,.7,0,Math.PI*2);display.fill();}display.drawImage(ink,0,0);by('inkUndo').disabled=!strokes.length;by('inkRedo').disabled=!redo.length;}
 function rebuild(){ic.clearRect(0,0,ink.width,ink.height);for(const s of strokes){if(s.points.length===1)segment(s,s.points[0],s.points[0]);else for(let i=1;i<s.points.length;i++)segment(s,s.points[i-1],s.points[i]);}paint();}
 function useTool(tool){inkTool=tool;by('inkPen').classList.toggle('selected',tool==='pen');by('inkEraser').classList.toggle('selected',tool==='eraser');by('inkPen').setAttribute('aria-pressed',tool==='pen');by('inkEraser').setAttribute('aria-pressed',tool==='eraser');}
 button.onclick=()=>{try{const selected=getPhysical()||{w:148,h:210};if(strokes.length&&(size.w!==selected.w||size.h!==selected.h)){if(!confirm('Changing page size will clear this handwriting canvas. Download strokes first if you want to keep them.'))return;strokes=[];redo=[];}size=selected;const scale=1600/Math.max(size.w,size.h);canvas.width=Math.max(100,Math.round(size.w*scale));canvas.height=Math.max(100,Math.round(size.h*scale));ink.width=canvas.width;ink.height=canvas.height;rebuild();by('inkSizeLabel').textContent=`${size.w} × ${size.h} mm · 5 mm dot grid`;by('inkDialog').showModal();}catch(e){notice(e.message,true);}};
 canvas.addEventListener('pointerdown',e=>{if(by('penOnly').checked&&e.pointerType!=='pen')return;if(active)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);active={pointerId:e.pointerId,tool:inkTool,color:'#26372d',widthMm:Number(by('inkWidth').value),points:[coords(e)]};segment(active,active.points[0],active.points[0]);paint();});
 canvas.addEventListener('pointermove',e=>{if(!active||active.pointerId!==e.pointerId)return;e.preventDefault();for(const event of e.getCoalescedEvents?.()||[e]){const p=coords(event),last=active.points.at(-1);active.points.push(p);segment(active,last,p);}paint();});
 function finish(e){if(!active||active.pointerId!==e.pointerId)return;const {pointerId,...stroke}=active;strokes.push(stroke);redo=[];active=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);paint();}
 canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);by('inkPen').onclick=()=>useTool('pen');by('inkEraser').onclick=()=>useTool('eraser');by('inkUndo').onclick=()=>{if(strokes.length){redo.push(strokes.pop());rebuild();}};by('inkRedo').onclick=()=>{if(redo.length){strokes.push(redo.pop());rebuild();}};by('inkClear').onclick=()=>{if(strokes.length&&confirm('Clear this handwriting page?')){strokes=[];redo=[];rebuild();}};by('closeInk').onclick=()=>by('inkDialog').close();
 by('inkDownload').onclick=()=>{const data={format:'jot-ink',version:1,page:{widthMm:size.w,heightMm:size.h},coordinates:'normalized',strokes};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'handwriting.jot-ink.json');};
 by('inkUse').onclick=()=>{loadCanvas(canvas,false);points=[{x:0,y:0},{x:source.width-1,y:0},{x:source.width-1,y:source.height-1},{x:0,y:source.height-1}];by('paperSize').value='custom';by('customWidth').value=size.w;by('customHeight').value=size.h;by('customDimensions').hidden=false;by('orientation').hidden=true;render();by('inkDialog').close();notice('Handwriting page ready. Download the editable strokes separately to preserve them.');};
 // Import the app's own stroke format; drawing data never executes code.
 const imp=document.createElement('button');imp.className='quiet';imp.textContent='Import strokes';const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;by('inkDownload').after(imp,input);imp.onclick=()=>input.click();input.onchange=async()=>{const file=input.files[0];input.value='';if(!file)return;try{if(file.size>15*1024*1024)throw Error('Stroke file exceeds 15 MB.');const d=JSON.parse(await file.text());if(d.format!=='jot-ink'||d.version!==1||d.coordinates!=='normalized'||!Array.isArray(d.strokes)||d.strokes.length>20000)throw Error('Unsupported stroke file.');const w=d.page?.widthMm,h=d.page?.heightMm;if(!Number.isFinite(w)||!Number.isFinite(h)||w<10||h<10||w>5000||h>5000)throw Error('Invalid page dimensions.');let count=0;for(const s of d.strokes){if(!['pen','eraser'].includes(s.tool)||!/^#[0-9a-f]{6}$/i.test(s.color)||!Number.isFinite(s.widthMm)||s.widthMm<=0||s.widthMm>5||!Array.isArray(s.points))throw Error('Invalid stroke.');count+=s.points.length;if(count>200000)throw Error('Too many stroke points.');for(const p of s.points)if(![p.x,p.y,p.pressure].every(v=>Number.isFinite(v)&&v>=0&&v<=1))throw Error('Invalid stroke coordinates.');}if(strokes.length&&!confirm('Replace this handwriting canvas with the imported strokes?'))return;size={w,h};strokes=d.strokes;redo=[];const scale=1600/Math.max(w,h);canvas.width=Math.max(100,Math.round(w*scale));canvas.height=Math.max(100,Math.round(h*scale));ink.width=canvas.width;ink.height=canvas.height;by('inkSizeLabel').textContent=`${w} × ${h} mm · imported strokes`;rebuild();}catch(e){notice(e.message,true);}};

 const insertJot=document.createElement('button');insertJot.className='button primary';insertJot.textContent='Insert in Jot';by('inkUse').after(insertJot);
 insertJot.onclick=async()=>{insertJot.disabled=true;try{const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),pngPath='assets/handwriting-'+id+'.png',inkPath='assets/handwriting-'+id+'.jot-ink.json';const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Unable to create the handwriting image.');const inkData={format:'jot-ink',version:1,page:{widthMm:size.w,heightMm:size.h},coordinates:'normalized',strokes};const {queueCapture}=await import('../jot/storage.mjs');await queueCapture({assets:[{path:pngPath,mediaType:'image/png',data:new Uint8Array(await blob.arrayBuffer())},{path:inkPath,mediaType:'application/json',data:new TextEncoder().encode(JSON.stringify(inkData))}],text:'![Handwritten page]('+pngPath+')\n\n[Editable handwriting strokes]('+inkPath+')'});window.location.href='../write/';}catch(e){notice('Could not insert handwriting: '+e.message,true);}finally{insertJot.disabled=false;}};
})();
